public interface IRenderer { void Circle(double r); }        // Implementor

public abstract class Shape(IRenderer renderer)              // Abstraction
{
    protected void RenderCircle(double r) => renderer.Circle(r);
    public abstract void Draw();
}

public sealed class Circle(IRenderer renderer, double radius) : Shape(renderer)
{
    public override void Draw() => RenderCircle(radius);
}
